def manage_scoreboard():
    """Manages a game scoreboard with add and remove points functions."""

    # Initialize the scoreboard with an empty dictionary
    scoreboard = {}

    def add_points(player, points):
        """Adds points to the scoreboard for a player."""
        if player not in scoreboard:
            scoreboard[player] = 0
        scoreboard[player] += points
        print(f"The score for {player} is now {scoreboard[player]}.")

    def remove_points(player, points):
        """Removes points from the scoreboard for a player."""
        if player in scoreboard:
            scoreboard[player] -= points
            if scoreboard[player] < 0:
                scoreboard[player] = 0
            print(f"{player} has removed {points} points from the scoreboard.")
        else:
            print(f"{player} does not have any points in the scoreboard.")

    while True:
        command = input("Enter 'add' to add points, 'remove' to remove points, or 'quit' to exit: ").lower()

        if command == 'add':
            player = input("Enter the player's name: ")
            points = int(input("Enter the number of points to add: "))
            add_points(player, points)

        elif command == 'remove':
            player = input("Enter the player's name: ")
            points = int(input("Enter the number of points to remove: "))
            remove_points(player, points)

        elif command == 'quit':
            break

        else:
            print("Invalid command. Please try again.")

    print("Goodbye!")


if __name__ == "__main__":
    manage_scoreboard()
```

This program allows users to add or remove points from the scoreboard and displays the current score after each operation. The `add_points` and `remove_points` functions ensure that the scoreboard remains valid and does not allow negative scores.
